/**
 * Hook definitions. Persisted in dataDir/hooks.json (0600, atomic writes); the file holds only a
 * SHA-256 hash of each hook's URL token, never the token itself.
 *
 * Why SHA-256 and not scrypt here: hook tokens are 256-bit random values generated by the Bridge, not passwords a
 * person chose, so a fast hash is already preimage-resistant, and the receiver must answer charting platforms within
 * their few-second webhook timeouts (an scrypt per request would also hand an attacker a cheap CPU amplifier). API keys, which a
 * person may paste around, are scrypt-hashed by auth.
 *
 * `generic` hooks also get an HMAC signing secret. HMAC verification needs the secret itself, so it is stored in the
 * encrypted SecretStore (deps.secrets, AES-256-GCM, name "hook:<id>") and cached in memory after first use.
 *
 * Both the token and the signing secret are returned exactly once, by create().
 */
import { createHash, randomBytes, timingSafeEqual } from "node:crypto";
import { join } from "node:path";
import { z } from "zod";
import { writeFileAtomic } from "../../lib/jsonl.mjs";
import { loadJsonOrQuarantine } from "../../lib/safeStore.mjs";
import { BridgeError, fromValidation } from "../core/errors.mjs";
import { parseSymbol } from "../core/symbolFormat.mjs";
import { IP_PRESET_NAMES, ipEntrySchema } from "./config.mjs";

export const HOOK_SOURCES = Object.freeze(["generic", "tradingview", "chartink", "gocharting"]);
/** TradingView hooks refuse alerts older than this many seconds unless the hook says otherwise. */
export const DEFAULT_MAX_AGE_SEC = 120;
const ACCOUNT_RE = /^[a-z0-9][a-z0-9-]{1,31}$/;
const HOOK_ID_RE = /^hk_[a-z2-7]{12}$/;
const B32 = "abcdefghijklmnopqrstuvwxyz234567";
const FILE_VERSION = 1;
/** lastSignalAt is written to disk at most this often (it is informational). */
const TOUCH_FLUSH_MS = 30_000;

/**
 * Body of POST /v1/hooks (openapi HookCreate). `side` is a webhook extension for sources whose alerts carry no side
 * (ChartInk scans, plain-text alerts); when set it also fixes the side for every other source.
 */
export const hookCreateSchema = z
  .object({
    source: z.enum(HOOK_SOURCES),
    label: z.string().trim().min(1).max(60),
    account: z.string().regex(ACCOUNT_RE, "use the account id from your config, such as dhan-main"),
    mode: z.enum(["paper", "live"]).default("paper"),
    requireConfirmation: z.boolean().default(false),
    allowedSymbols: z.array(z.string().min(3).max(64)).max(500).optional(),
    maxLotsPerSignal: z.number().int().min(1).max(1000).default(1),
    product: z.enum(["CNC", "INTRADAY", "MARGIN"]).optional(),
    orderType: z.enum(["LIMIT", "MARKET", "SL", "SL-M"]).default("LIMIT"),
    allowSourceIps: z.array(ipEntrySchema).max(50).optional(),
    side: z.enum(["BUY", "SELL"]).optional(),
    /** Live mode on a source that cannot sign its alerts (only the URL token protects it): the person says so. */
    acknowledgeUnsignedLive: z.boolean().default(false),
    /** An alert whose own time is older than this many seconds is refused as stale (needs `time` in the alert). */
    maxAgeSec: z.number().int().min(5).max(3600).nullable().optional(),
    /** Also accept alerts only from a published address list kept in the hooks config (for example "tradingview"). */
    sourceIpPreset: z.enum(IP_PRESET_NAMES).nullable().optional(),
  })
  .strict()
  .superRefine((o, ctx) => {
    // A ChartInk scan sends one price per stock and nothing else, so it cannot say where a stop should wait.
    if (o.source === "chartink" && (o.orderType === "SL" || o.orderType === "SL-M")) {
      ctx.addIssue({ code: "custom", path: ["orderType"], message: "ChartInk alerts carry one price and no trigger, so a ChartInk hook places LIMIT or MARKET orders." });
    }
  });

/**
 * @typedef {{ id: string, source: "generic"|"tradingview"|"chartink"|"gocharting", label: string, account: string,
 *   mode: "paper"|"live", requireConfirmation: boolean, allowedSymbols: string[], maxLotsPerSignal: number,
 *   product: "CNC"|"INTRADAY"|"MARGIN"|null, orderType: "LIMIT"|"MARKET"|"SL"|"SL-M", allowSourceIps: string[], side: "BUY"|"SELL"|null,
 *   maxAgeSec: number | null, sourceIpPreset: "tradingview" | null, passphraseHash: string | null,
 *   tokenHash: string, createdAt: string, lastSignalAt: string | null }} HookRecord
 */

/** SHA-256 hex of a token. */
export const hashToken = (token) => createHash("sha256").update(String(token), "utf8").digest("hex");

const newHookId = () => {
  const b = randomBytes(12);
  let s = "";
  for (let i = 0; i < 12; i += 1) s += B32[b[i] & 31];
  return `hk_${s}`;
};

/** Public view (openapi Hook): never the token hash. */
export function publicHook(h) {
  return {
    id: h.id,
    source: h.source,
    label: h.label,
    account: h.account,
    mode: h.mode,
    requireConfirmation: h.requireConfirmation,
    allowedSymbols: [...h.allowedSymbols],
    maxLotsPerSignal: h.maxLotsPerSignal,
    product: h.product,
    orderType: h.orderType,
    side: h.side,
    allowSourceIps: [...h.allowSourceIps],
    sourceIpPreset: h.sourceIpPreset ?? null,
    maxAgeSec: h.maxAgeSec ?? null,
    hasPassphrase: typeof h.passphraseHash === "string",
    acknowledgeUnsignedLive: h.acknowledgeUnsignedLive === true,
    createdByKeyId: h.createdByKeyId ?? null,
    createdAt: h.createdAt,
    lastSignalAt: h.lastSignalAt,
  };
}

/** Canonicalise allowed symbols (lenient input; throws VALIDATION_FAILED naming the bad entry). */
function canonicalSymbols(list) {
  const out = [];
  for (const [i, s] of (list ?? []).entries()) {
    try {
      out.push(parseSymbol(s).canonical);
    } catch {
      throw new BridgeError("VALIDATION_FAILED", `allowedSymbols[${i}] (${String(s).slice(0, 64)}) is not a symbol the Bridge understands.`, {
        errors: [{ path: `allowedSymbols.${i}`, message: "use a canonical symbol such as NSE:RELIANCE or NFO:NIFTY-2026-10-27-25000-CE" }],
      });
    }
  }
  return [...new Set(out)];
}

/**
 * @param {{ dataDir: string, secrets?: { get(name: string): Promise<object|null>, set(name: string, v: object): Promise<void>, delete(name: string): Promise<boolean> },
 *   now?: () => number, maxHooks?: number, logger?: { warn(m: string, f?: object): void, addSecret?(v: string): void },
 *   istIso?: (ms: number) => string }} opts
 */
export function createHookStore({ dataDir, secrets, now = () => Date.now(), maxHooks = 100, logger, istIso = defaultIstIso }) {
  const file = join(dataDir, "hooks.json");
  /** @type {Map<string, HookRecord>} */
  const byId = new Map();
  /** tokenHash -> id */
  const byHash = new Map();
  /** id -> signing secret (generic hooks), loaded lazily */
  const secretCache = new Map();
  let touchTimer = null;
  let dirty = false;

  const load = () => {
    // A damaged or empty hooks.json (a power cut after an un-synced rename) is moved aside and the Bridge starts with
    // no hooks: the alert URLs are gone with it, so the hooks have to be created again.
    const { value: parsed, quarantinedTo } = loadJsonOrQuarantine(file, {
      what: "alert hooks (hooks.json)",
      log: logger,
      validate: (v) => (v && v.version === FILE_VERSION && Array.isArray(v.hooks)) || "has an unknown format",
    });
    if (quarantinedTo) logger?.warn("The alert hooks have to be created again; the damaged file is kept for reference.", { file: quarantinedTo });
    if (!parsed) return;
    for (const h of parsed.hooks) {
      if (!h || !HOOK_ID_RE.test(h.id) || !/^[0-9a-f]{64}$/.test(h.tokenHash) || !HOOK_SOURCES.includes(h.source)) {
        logger?.warn("hooks.json: skipping a malformed hook entry");
        continue;
      }
      const rec = {
        allowedSymbols: [],
        allowSourceIps: [],
        product: null,
        side: null,
        maxAgeSec: null,
        sourceIpPreset: null,
        passphraseHash: null,
        lastSignalAt: null,
        requireConfirmation: false,
        orderType: "LIMIT",
        mode: "paper",
        maxLotsPerSignal: 1,
        ...h,
      };
      byId.set(rec.id, rec);
      byHash.set(rec.tokenHash, rec.id);
    }
  };

  const persist = () => {
    writeFileAtomic(file, `${JSON.stringify({ version: FILE_VERSION, hooks: [...byId.values()] }, null, 2)}\n`);
    dirty = false;
  };

  load();

  return {
    /** Hooks, oldest first. @returns {HookRecord[]} */
    list() {
      return [...byId.values()].sort((a, b) => a.createdAt.localeCompare(b.createdAt));
    },

    /** @param {string} id @returns {HookRecord | null} */
    get(id) {
      return byId.get(String(id)) ?? null;
    },

    /**
     * Find a hook by the token in its URL. O(1); the map is keyed by the token's SHA-256, so lookup time does not
     * depend on how much of a guessed token is right.
     * @param {string} token
     * @returns {HookRecord | null}
     */
    findByToken(token) {
      if (typeof token !== "string" || token.length < 32 || token.length > 128) return null;
      const id = byHash.get(hashToken(token));
      return id ? (byId.get(id) ?? null) : null;
    },

    /**
     * Create a hook. Returns the URL token (and, for generic hooks, the signing secret) ONCE.
     * @param {unknown} input  HookCreate
     * @param {{ createdByKeyId?: string | null }} [opts]  the API key that created it (audited; a live hook stops
     *   accepting signals when that key is revoked)
     * @returns {Promise<{ hook: HookRecord, token: string, signingSecret: string | null, passphrase: string | null }>}
     *   passphrase: TradingView hooks only; only its SHA-256 is kept
     */
    async create(input, { createdByKeyId = null } = {}) {
      const parsed = hookCreateSchema.safeParse(input);
      if (!parsed.success) throw fromValidation(parsed.error, "The hook definition is not valid.");
      const d = parsed.data;
      if (byId.size >= maxHooks) throw new BridgeError("VALIDATION_FAILED", `You already have ${byId.size} hooks, the most allowed (hooks.maxHooks). Delete one first.`);
      const token = randomBytes(32).toString("base64url");
      const id = newHookId();
      let signingSecret = null;
      if (d.source === "generic") {
        if (!secrets) throw new BridgeError("NOT_IMPLEMENTED", "Signed generic hooks need the encrypted secret store.");
        signingSecret = randomBytes(32).toString("base64url");
        await secrets.set(`hook:${id}`, { signingSecret });
        secretCache.set(id, signingSecret);
      }
      // TradingView cannot sign, so its alerts carry a passphrase in the message. It is random (128 bits), shown once,
      // and only its hash is stored (compared in constant time).
      const passphrase = d.source === "tradingview" ? randomBytes(16).toString("base64url") : null;
      logger?.addSecret?.(token);
      if (signingSecret) logger?.addSecret?.(signingSecret);
      if (passphrase) logger?.addSecret?.(passphrase);
      const maxAgeSec = d.maxAgeSec !== undefined ? d.maxAgeSec : d.source === "tradingview" ? DEFAULT_MAX_AGE_SEC : null;
      if (d.mode === "live" && d.source === "tradingview" && maxAgeSec === null) {
        throw new BridgeError("VALIDATION_FAILED", "A live TradingView hook needs maxAgeSec, so an old or replayed alert can never place a real order.", { errors: [{ path: "maxAgeSec", message: "required for a live TradingView hook (5 to 3600 seconds)" }] });
      }
      /** @type {HookRecord} */
      const hook = {
        id,
        source: d.source,
        label: d.label,
        account: d.account,
        mode: d.mode,
        requireConfirmation: d.requireConfirmation,
        allowedSymbols: canonicalSymbols(d.allowedSymbols),
        maxLotsPerSignal: d.maxLotsPerSignal,
        product: d.product ?? null,
        orderType: d.orderType,
        allowSourceIps: [...new Set(d.allowSourceIps ?? [])],
        side: d.side ?? null,
        maxAgeSec,
        sourceIpPreset: d.sourceIpPreset ?? null,
        passphraseHash: passphrase ? hashToken(passphrase) : null,
        acknowledgeUnsignedLive: d.acknowledgeUnsignedLive === true,
        createdByKeyId: typeof createdByKeyId === "string" ? createdByKeyId : null,
        tokenHash: hashToken(token),
        createdAt: istIso(now()),
        lastSignalAt: null,
      };
      byId.set(id, hook);
      byHash.set(hook.tokenHash, id);
      try {
        persist();
      } catch (err) {
        byId.delete(id);
        byHash.delete(hook.tokenHash);
        secretCache.delete(id);
        throw err;
      }
      return { hook, token, signingSecret, passphrase };
    },

    /**
     * Delete a hook; its URL stops working at once.
     * @param {string} id
     * @returns {Promise<HookRecord>} throws NOT_FOUND
     */
    async remove(id) {
      const hook = byId.get(String(id));
      if (!hook) throw new BridgeError("NOT_FOUND", "No hook with this id.");
      byId.delete(hook.id);
      byHash.delete(hook.tokenHash);
      secretCache.delete(hook.id);
      persist();
      if (hook.source === "generic" && secrets) {
        try {
          await secrets.delete(`hook:${hook.id}`);
        } catch (err) {
          logger?.warn("hook signing secret could not be deleted", { hookId: hook.id, code: err?.code });
        }
      }
      return hook;
    },

    /**
     * The signing secret of a generic hook (null when missing).
     * @param {string} id
     * @returns {Promise<string | null>}
     */
    async signingSecret(id) {
      if (secretCache.has(id)) return secretCache.get(id);
      if (!secrets) return null;
      const v = await secrets.get(`hook:${id}`);
      const s = typeof v?.signingSecret === "string" ? v.signingSecret : null;
      if (s) secretCache.set(id, s);
      return s;
    },

    /**
     * Whether `given` is this hook's passphrase. Both sides are hashed first, so the comparison runs over equal-length
     * digests in constant time whatever was sent; a hook without a passphrase never matches.
     * @param {string} id @param {unknown} given
     */
    checkPassphrase(id, given) {
      const h = byId.get(id);
      const a = createHash("sha256").update(typeof given === "string" ? given : "", "utf8").digest();
      const b = Buffer.from(typeof h?.passphraseHash === "string" ? h.passphraseHash : "0".repeat(64), "hex");
      return timingSafeEqual(a, b) && typeof h?.passphraseHash === "string";
    },

    /** Record that a hook received a signal (written to disk lazily). */
    touch(id) {
      const h = byId.get(id);
      if (!h) return;
      h.lastSignalAt = istIso(now());
      dirty = true;
      if (!touchTimer) {
        touchTimer = setTimeout(() => {
          touchTimer = null;
          if (dirty) {
            try {
              persist();
            } catch (err) {
              logger?.warn("hooks.json could not be saved", { message: err?.message });
            }
          }
        }, TOUCH_FLUSH_MS);
        touchTimer.unref?.();
      }
    },

    /** Write pending changes and stop timers (module stop). */
    close() {
      if (touchTimer) clearTimeout(touchTimer);
      touchTimer = null;
      if (dirty) persist();
    },

    /** Path of the backing file (diagnostics, tests). */
    file,
  };
}

/** ISO-8601 in IST (+05:30), millisecond precision. */
export function defaultIstIso(ms) {
  const d = new Date(ms + 19_800_000);
  return `${d.toISOString().slice(0, 23)}+05:30`;
}
